//! `json5.loads` of Python's json5 0.12.0, the parser the SNS indexer runs.
//!
//! The parser is a rule-for-rule transliteration of `json5/parser.py`
//! (generated by glop 0.8.3) and `json5/lib.py` (`parse`, `_convert`,
//! `_walk_ast`). Each Python method and lambda is one call to `P::frame`,
//! so the parser stacks exactly the Python frames the original does. Python
//! raises `RecursionError` once the stack passes its recursion limit, which
//! deep nesting reaches; [`FRAME_LIMIT`] is the deepest parser frame the SNS
//! indexer survives. Strings are code point vectors because a `\uXXXX`
//! escape yields a lone surrogate, which Python keeps and Rust strings cannot
//! hold.

use std::rc::Rc;

use crate::pytables::{LL, LM, LO, LT, LU, MC, MN, ND, NL, PC, ZS};

/// Deepest frame of the generated parser, counting `Parser._grammar_` as 1,
/// that stays within Python's default recursion limit of 1000 when
/// `json5.loads` runs inside `sns_index.py`'s `index_block` →
/// `get_sns_name` (`<module>`, `index_block`, `get_sns_name`, `loads`,
/// `parse` and `Parser.parse` hold the other six frames).
pub const FRAME_LIMIT: u32 = 994;

/// A value `json5.loads` returns.
#[derive(Debug, Clone, PartialEq)]
pub enum PyValue {
    None,
    Bool(bool),
    /// An `int` or `float`; the SNS rules never read its value.
    Number,
    Str(Vec<u32>),
    List(Vec<PyValue>),
    /// A `dict` in insertion order; a repeated key keeps its first position
    /// and its last value, as `dict(pairs)` does.
    Dict(Vec<(Vec<u32>, PyValue)>),
}

impl PyValue {
    /// `dict[key]` for a dict.
    pub fn get(&self, key: &str) -> Option<&PyValue> {
        match self {
            PyValue::Dict(pairs) => pairs.iter().find(|(k, _)| cps_eq(k, key)).map(|(_, v)| v),
            _ => None,
        }
    }

    /// `self == key` for a Python `str` key.
    pub fn is_str(&self, s: &str) -> bool {
        matches!(self, PyValue::Str(cps) if cps_eq(cps, s))
    }
}

fn cps_eq(cps: &[u32], s: &str) -> bool {
    cps.iter().copied().eq(s.chars().map(u32::from))
}

/// `json5.loads(content)`; `None` when it raises (`ValueError` or
/// `RecursionError`).
pub fn loads(content: &str) -> Option<PyValue> {
    let msg: Vec<u32> = content.chars().map(u32::from).collect();
    let mut parser = P::new(msg, FRAME_LIMIT);
    let ast = parser.run().ok()??;
    walk(&ast).ok()
}

/// The deepest frame the parser reaches on `content` and the number of
/// frames it enters, without a recursion limit; the parity fixtures pin both
/// against Python.
pub fn frame_stats(content: &str) -> (u32, u64) {
    let msg: Vec<u32> = content.chars().map(u32::from).collect();
    let mut parser = P::new(msg, u32::MAX);
    let _ = parser.run();
    (parser.max_depth, parser.calls)
}

// ---------------------------------------------------------------------------
// AST conversion: json5/lib.py `_convert` and `_walk_ast`.

struct ValueError;

fn walk(el: &V) -> Result<PyValue, ValueError> {
    if let V::Str(s) = el {
        return match tag(s) {
            "None" => Ok(PyValue::None),
            "True" => Ok(PyValue::Bool(true)),
            "False" => Ok(PyValue::Bool(false)),
            _ => unreachable!("bare string in the json5 AST"),
        };
    }
    let items = el.list();
    let (ty, v) = (tag(items[0].str()), &items[1]);
    match ty {
        "number" => number(v.str()).map(|()| PyValue::Number),
        "string" => Ok(PyValue::Str(v.str().to_vec())),
        "object" => {
            let mut pairs: Vec<(Vec<u32>, PyValue)> = Vec::new();
            for member in v.list() {
                let member = member.list();
                let key = member[0].str().to_vec();
                let value = walk(&member[1])?;
                match pairs.iter_mut().find(|(k, _)| *k == key) {
                    Some(pair) => pair.1 = value,
                    None => pairs.push((key, value)),
                }
            }
            Ok(PyValue::Dict(pairs))
        }
        "array" => v
            .list()
            .iter()
            .map(walk)
            .collect::<Result<_, _>>()
            .map(PyValue::List),
        other => unreachable!("unknown json5 AST node {other}"),
    }
}

/// ASCII tags of the AST; anything else maps to "".
fn tag(s: &[u32]) -> &'static str {
    const TAGS: [&str; 7] = [
        "None", "True", "False", "number", "string", "object", "array",
    ];
    TAGS.into_iter().find(|t| cps_eq(s, t)).unwrap_or("")
}

/// Whether `_walk_ast` converts the number literal `v` without raising:
/// `int(v, base=16)` for `0x`, `float(v)` when it holds `.`, `e` or `E`,
/// `float` of `Infinity`/`NaN`, and `int(v)` otherwise. A sign before `0x`
/// reaches `float` or `int` and raises, as does a fraction or exponent
/// without digits, and `int` raises past 4300 digits
/// (`sys.int_info.default_max_str_digits`).
fn number(v: &[u32]) -> Result<(), ValueError> {
    let s: String = v.iter().filter_map(|&c| char::from_u32(c)).collect();
    if s.starts_with("0x") || s.starts_with("0X") {
        return Ok(());
    }
    if s.contains(['.', 'e', 'E']) {
        let body = s.strip_prefix('-').unwrap_or(&s);
        if body.contains(['x', 'X']) {
            return Err(ValueError);
        }
        let (mantissa, exponent) = match body.find(['e', 'E']) {
            Some(at) => (&body[..at], Some(&body[at + 1..])),
            None => (body, None),
        };
        let mantissa_digits = mantissa.bytes().any(|b| b.is_ascii_digit());
        let exponent_digits = exponent.is_none_or(|e| {
            e.trim_start_matches(['+', '-'])
                .bytes()
                .any(|b| b.is_ascii_digit())
        });
        return if mantissa_digits && exponent_digits {
            Ok(())
        } else {
            Err(ValueError)
        };
    }
    if s.contains("Infinity") || s.contains("NaN") {
        return Ok(());
    }
    let digits = s.strip_prefix('-').unwrap_or(&s);
    if digits.contains(['x', 'X']) || digits.len() > 4300 {
        return Err(ValueError);
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// The parser.

#[derive(Clone, Debug)]
enum V {
    Nil,
    Bool(bool),
    Str(Rc<[u32]>),
    List(Rc<Vec<V>>),
}

impl V {
    fn ch(c: u32) -> V {
        V::Str(Rc::from([c].as_slice()))
    }

    fn text(s: &str) -> V {
        V::Str(s.chars().map(u32::from).collect())
    }

    fn list(&self) -> &[V] {
        match self {
            V::List(items) => items,
            other => unreachable!("expected a list, found {other:?}"),
        }
    }

    fn str(&self) -> &[u32] {
        match self {
            V::Str(s) => s,
            other => unreachable!("expected a string, found {other:?}"),
        }
    }

    fn truthy(&self) -> bool {
        match self {
            V::Nil => false,
            V::Bool(b) => *b,
            V::Str(s) => !s.is_empty(),
            V::List(items) => !items.is_empty(),
        }
    }

    /// Python `a + b` on two strings or two lists.
    fn add(&self, other: &V) -> V {
        match (self, other) {
            (V::Str(a), V::Str(b)) => V::Str(a.iter().chain(b.iter()).copied().collect()),
            (V::List(a), V::List(b)) => {
                V::List(Rc::new(a.iter().chain(b.iter()).cloned().collect()))
            }
            (a, b) => unreachable!("cannot add {a:?} and {b:?}"),
        }
    }

    fn new_list(items: Vec<V>) -> V {
        V::List(Rc::new(items))
    }
}

/// `RecursionError`.
struct Recursion;

type R<T = ()> = Result<T, Recursion>;
type Rule<'r> = &'r dyn Fn(&mut P) -> R;

struct P {
    msg: Vec<u32>,
    pos: usize,
    val: V,
    failed: bool,
    scopes: Vec<Vec<(&'static str, V)>>,
    depth: u32,
    max_depth: u32,
    calls: u64,
    limit: u32,
}

impl P {
    fn new(msg: Vec<u32>, limit: u32) -> P {
        P {
            msg,
            pos: 0,
            val: V::Nil,
            failed: false,
            scopes: Vec::new(),
            depth: 0,
            max_depth: 0,
            calls: 0,
            limit,
        }
    }

    /// `Parser.parse` after `lib.parse` rejects empty input: the AST, or
    /// `None` when the grammar fails.
    fn run(&mut self) -> R<Option<V>> {
        if self.msg.is_empty() {
            return Ok(None);
        }
        self.grammar()?;
        if self.failed {
            // `_err_str` and the `_err_offsets` it calls build the message.
            self.frame(|p| p.frame(|_| Ok(())))?;
            return Ok(None);
        }
        Ok(Some(self.val.clone()))
    }

    /// One Python frame around `body`.
    fn frame<T>(&mut self, body: impl FnOnce(&mut P) -> R<T>) -> R<T> {
        self.depth += 1;
        self.calls += 1;
        self.max_depth = self.max_depth.max(self.depth);
        if self.depth > self.limit {
            return Err(Recursion);
        }
        let result = body(self);
        self.depth -= 1;
        result
    }

    // --- glop runtime -----------------------------------------------------

    fn succeed(&mut self, v: V, newpos: Option<usize>) -> R {
        self.frame(|p| {
            p.val = v;
            p.failed = false;
            if let Some(newpos) = newpos {
                p.pos = newpos;
            }
            Ok(())
        })
    }

    fn fail(&mut self) -> R {
        self.frame(|p| {
            p.val = V::Nil;
            p.failed = true;
            Ok(())
        })
    }

    fn rewind(&mut self, newpos: usize) -> R {
        self.frame(|p| p.succeed(V::Nil, Some(newpos)))
    }

    fn bind(&mut self, rule: Rule, var: &'static str) -> R {
        self.frame(|p| {
            rule(p)?;
            if !p.failed {
                let v = p.val.clone();
                p.set(var, v)?;
            }
            Ok(())
        })
    }

    fn not(&mut self, rule: Rule) -> R {
        self.frame(|p| {
            let pos = p.pos;
            rule(p)?;
            if p.failed {
                p.succeed(V::Nil, Some(pos))
            } else {
                p.rewind(pos)?;
                p.fail()
            }
        })
    }

    fn opt(&mut self, rule: Rule) -> R {
        self.frame(|p| {
            let pos = p.pos;
            rule(p)?;
            if p.failed {
                p.succeed(V::new_list(Vec::new()), Some(pos))
            } else {
                let v = p.val.clone();
                p.succeed(V::new_list(vec![v]), None)
            }
        })
    }

    fn plus(&mut self, rule: Rule) -> R {
        self.frame(|p| {
            rule(p)?;
            let vs = vec![p.val.clone()];
            if p.failed {
                return Ok(());
            }
            p.star_from(rule, vs)
        })
    }

    fn star(&mut self, rule: Rule) -> R {
        self.star_from(rule, Vec::new())
    }

    fn star_from(&mut self, rule: Rule, mut vs: Vec<V>) -> R {
        self.frame(|p| {
            loop {
                let pos = p.pos;
                rule(p)?;
                if p.failed {
                    p.rewind(pos)?;
                    break;
                }
                vs.push(p.val.clone());
            }
            p.succeed(V::new_list(vs), None)
        })
    }

    fn seq(&mut self, rules: &[Rule]) -> R {
        self.frame(|p| {
            for rule in rules {
                rule(p)?;
                if p.failed {
                    break;
                }
            }
            Ok(())
        })
    }

    fn choose(&mut self, rules: &[Rule]) -> R {
        self.frame(|p| {
            let pos = p.pos;
            let (last, rest) = rules.split_last().expect("choose without rules");
            for rule in rest {
                rule(p)?;
                if !p.failed {
                    return Ok(());
                }
                p.rewind(pos)?;
            }
            last(p)
        })
    }

    fn ch(&mut self, c: char) -> R {
        self.frame(|p| {
            let c = u32::from(c);
            if p.pos < p.msg.len() && p.msg[p.pos] == c {
                let next = p.pos + 1;
                p.succeed(V::ch(c), Some(next))
            } else {
                p.fail()
            }
        })
    }

    fn str_(&mut self, s: &'static str) -> R {
        self.frame(|p| {
            for c in s.chars() {
                p.ch(c)?;
                if p.failed {
                    return Ok(());
                }
            }
            p.val = V::text(s);
            Ok(())
        })
    }

    fn range(&mut self, lo: char, hi: char) -> R {
        self.frame(|p| {
            if p.pos != p.msg.len() && (u32::from(lo)..=u32::from(hi)).contains(&p.msg[p.pos]) {
                let (c, next) = (p.msg[p.pos], p.pos + 1);
                p.succeed(V::ch(c), Some(next))
            } else {
                p.fail()
            }
        })
    }

    fn push(&mut self) -> R {
        self.frame(|p| {
            p.scopes.push(Vec::new());
            Ok(())
        })
    }

    fn pop(&mut self) -> R {
        self.frame(|p| {
            p.scopes.pop();
            Ok(())
        })
    }

    /// The innermost scope's `var`, else the global variable.
    fn get(&mut self, var: &'static str) -> R<V> {
        self.frame(|p| {
            if let Some((_, v)) = p
                .scopes
                .last()
                .and_then(|scope| scope.iter().find(|(name, _)| *name == var))
            {
                return Ok(v.clone());
            }
            match var {
                "_strict" | "_consume_trailing" => Ok(V::Bool(true)),
                other => unreachable!("json5 parser reads unset variable {other}"),
            }
        })
    }

    fn set(&mut self, var: &'static str, v: V) -> R {
        self.frame(|p| {
            let scope = p
                .scopes
                .last_mut()
                .expect("json5 parser sets outside a scope");
            match scope.iter_mut().find(|(name, _)| *name == var) {
                Some(slot) => slot.1 = v,
                None => scope.push((var, v)),
            }
            Ok(())
        })
    }

    fn is_unicat(&mut self, x: &V, category: &[(u32, u32)]) -> R<bool> {
        let c = x.str()[0];
        self.frame(|_| Ok(crate::pystr::in_ranges(category, c)))
    }

    fn join(&mut self, vs: &V) -> R<V> {
        self.frame(|_| {
            Ok(V::Str(
                vs.list()
                    .iter()
                    .flat_map(|v| v.str().iter().copied())
                    .collect(),
            ))
        })
    }

    fn xtou(&mut self, s: &V) -> R<V> {
        self.frame(|_| {
            let hex: String = s.str().iter().filter_map(|&c| char::from_u32(c)).collect();
            Ok(V::ch(u32::from_str_radix(&hex, 16).expect("hex digits")))
        })
    }

    fn anything(&mut self) -> R {
        self.frame(|p| {
            if p.pos < p.msg.len() {
                let (c, next) = (p.msg[p.pos], p.pos + 1);
                p.succeed(V::ch(c), Some(next))
            } else {
                p.fail()
            }
        })
    }

    fn end(&mut self) -> R {
        self.frame(|p| {
            if p.pos == p.msg.len() {
                p.succeed(V::Nil, None)
            } else {
                p.fail()
            }
        })
    }

    /// A lambda frame.
    fn lam(&mut self, body: impl FnOnce(&mut P) -> R) -> R {
        self.frame(body)
    }

    /// `v = self._get(var); if v: succeed(v) else: fail()`.
    fn flag(&mut self, var: &'static str) -> R {
        let v = self.get(var)?;
        if v.truthy() {
            self.succeed(v, None)
        } else {
            self.fail()
        }
    }

    /// `v = self._is_unicat(self._get('x'), cat); if v: succeed(v) else: fail()`.
    fn unicat_check(&mut self, category: &[(u32, u32)]) -> R {
        let x = self.get("x")?;
        if self.is_unicat(&x, category)? {
            self.succeed(V::Bool(true), None)
        } else {
            self.fail()
        }
    }

    /// `lambda: self._succeed(self._get(var))`.
    fn lam_succeed_get(&mut self, var: &'static str) -> R {
        self.lam(|p| {
            let v = p.get(var)?;
            p.succeed(v, None)
        })
    }

    /// `lambda: self._succeed(<constant>)`.
    fn lam_succeed(&mut self, v: V) -> R {
        self.lam(|p| p.succeed(v, None))
    }

    /// `lambda: self._bind(<rule>, var)`.
    fn lam_bind(&mut self, rule: Rule, var: &'static str) -> R {
        self.lam(|p| p.bind(rule, var))
    }

    /// `lambda: self._ch(c)`.
    fn lam_ch(&mut self, c: char) -> R {
        self.lam(|p| p.ch(c))
    }

    /// `lambda: self._str(s)`.
    fn lam_str(&mut self, s: &'static str) -> R {
        self.lam(|p| p.str_(s))
    }

    /// `lambda: self._not(<rule>)`.
    fn lam_not(&mut self, rule: Rule) -> R {
        self.lam(|p| p.not(rule))
    }

    /// `lambda: self._star(<rule>)`.
    fn lam_star(&mut self, rule: Rule) -> R {
        self.lam(|p| p.star(rule))
    }

    /// A method that pushes a scope, runs `seq(rules)` and pops it.
    fn scoped_seq(&mut self, rules: &[Rule]) -> R {
        self.frame(|p| {
            p.push()?;
            p.seq(rules)?;
            p.pop()
        })
    }

    // --- grammar ----------------------------------------------------------

    fn grammar(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.sp(),
            &|p| p.lam_bind(&|p| p.value(), "v"),
            &|p| p.trailing(),
            &|p| p.lam_succeed_get("v"),
        ])
    }

    fn trailing(&mut self) -> R {
        self.frame(|p| p.choose(&[&|p| p.trailing_c0(), &|p| p.trailing_c1()]))
    }

    fn trailing_c0(&mut self) -> R {
        self.frame(|p| {
            p.seq(&[
                &|p| p.frame(|p| p.flag("_consume_trailing")),
                &|p| p.sp(),
                &|p| p.end(),
            ])
        })
    }

    fn trailing_c1(&mut self) -> R {
        self.frame(|p| p.not(&|p| p.frame(|p| p.flag("_consume_trailing"))))
    }

    fn sp(&mut self) -> R {
        self.frame(|p| p.star(&|p| p.ws()))
    }

    fn ws(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.frame(|p| p.ch(' ')),
                &|p| p.eol(),
                &|p| p.comment(),
                &|p| p.frame(|p| p.ch('\t')),
                &|p| p.frame(|p| p.ch('\u{b}')),
                &|p| p.frame(|p| p.ch('\u{c}')),
                &|p| p.frame(|p| p.ch('\u{a0}')),
                &|p| p.frame(|p| p.ch('\u{feff}')),
                &|p| p.ws_c8(),
            ])
        })
    }

    fn ws_c8(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.ws_c8_s0(),
            &|p| p.lam_bind(&|p| p.anything(), "x"),
            &|p| p.lam_succeed_get("x"),
        ])
    }

    fn ws_c8_s0(&mut self) -> R {
        self.frame(|p| p.not(&|p| p.lam_not(&|p| p.ws_c8_s0_n_n())))
    }

    fn ws_c8_s0_n_n(&mut self) -> R {
        self.frame(|p| p.lam(|p| p.choose(&[&|p| p.ws_c8_s0_n_n_g_c0()])))
    }

    fn ws_c8_s0_n_n_g_c0(&mut self) -> R {
        self.frame(|p| {
            p.seq(&[&|p| p.lam_bind(&|p| p.anything(), "x"), &|p| {
                p.frame(|p| p.unicat_check(ZS))
            }])
        })
    }

    fn eol(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.frame(|p| p.seq(&[&|p| p.lam_ch('\r'), &|p| p.lam_ch('\n')])),
                &|p| p.frame(|p| p.ch('\r')),
                &|p| p.frame(|p| p.ch('\n')),
                &|p| p.frame(|p| p.ch('\u{2028}')),
                &|p| p.frame(|p| p.ch('\u{2029}')),
            ])
        })
    }

    fn comment(&mut self) -> R {
        self.frame(|p| p.choose(&[&|p| p.comment_c0(), &|p| p.comment_c1()]))
    }

    fn comment_c0(&mut self) -> R {
        self.frame(|p| {
            p.seq(&[&|p| p.lam_str("//"), &|p| {
                p.lam_star(&|p| {
                    p.frame(|p| p.seq(&[&|p| p.lam_not(&|p| p.eol()), &|p| p.anything()]))
                })
            }])
        })
    }

    fn comment_c1(&mut self) -> R {
        self.frame(|p| {
            p.seq(&[
                &|p| p.lam_str("/*"),
                &|p| {
                    p.frame(|p| {
                        p.star(&|p| {
                            p.lam(|p| {
                                p.seq(&[&|p| p.frame(|p| p.not(&|p| p.lam_str("*/"))), &|p| {
                                    p.anything()
                                }])
                            })
                        })
                    })
                },
                &|p| p.lam_str("*/"),
            ])
        })
    }

    fn value(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.value_literal("null", "None"),
                &|p| p.value_literal("true", "True"),
                &|p| p.value_literal("false", "False"),
                &|p| p.value_node(&|p| p.object(), "object"),
                &|p| p.value_node(&|p| p.array(), "array"),
                &|p| p.value_node(&|p| p.string(), "string"),
                &|p| p.value_node(&|p| p.num_literal(), "number"),
            ])
        })
    }

    /// `_value__c0_` to `_value__c2_`.
    fn value_literal(&mut self, word: &'static str, tag: &'static str) -> R {
        self.frame(|p| p.seq(&[&|p| p.lam_str(word), &|p| p.lam_succeed(V::text(tag))]))
    }

    /// `_value__c3_` to `_value__c6_`.
    fn value_node(&mut self, rule: Rule, tag: &'static str) -> R {
        self.scoped_seq(&[&|p| p.lam_bind(rule, "v"), &|p| {
            p.lam(|p| {
                let v = p.get("v")?;
                p.succeed(V::new_list(vec![V::text(tag), v]), None)
            })
        }])
    }

    fn object(&mut self) -> R {
        self.frame(|p| {
            p.choose(
                &[&|p| p.container_c0('{', &|p| p.member_list(), '}'), &|p| {
                    p.container_c1('{', '}')
                }],
            )
        })
    }

    fn array(&mut self) -> R {
        self.frame(|p| {
            p.choose(
                &[&|p| p.container_c0('[', &|p| p.element_list(), ']'), &|p| {
                    p.container_c1('[', ']')
                }],
            )
        })
    }

    /// `_object__c0_` and `_array__c0_`.
    fn container_c0(&mut self, open: char, items: Rule, close: char) -> R {
        self.scoped_seq(&[
            &|p| p.lam_ch(open),
            &|p| p.sp(),
            &|p| p.lam_bind(items, "v"),
            &|p| p.sp(),
            &|p| p.lam_ch(close),
            &|p| p.lam_succeed_get("v"),
        ])
    }

    /// `_object__c1_` and `_array__c1_`.
    fn container_c1(&mut self, open: char, close: char) -> R {
        self.frame(|p| {
            p.seq(&[
                &|p| p.lam_ch(open),
                &|p| p.sp(),
                &|p| p.lam_ch(close),
                &|p| p.lam_succeed(V::new_list(Vec::new())),
            ])
        })
    }

    fn string(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[&|p| p.string_c(&|p| p.squote(), &|p| p.sqchar()), &|p| {
                p.string_c(&|p| p.dquote(), &|p| p.dqchar())
            }])
        })
    }

    /// `_string__c0_` and `_string__c1_`.
    fn string_c(&mut self, quote: Rule, char_rule: Rule) -> R {
        self.scoped_seq(&[
            quote,
            &|p| p.frame(|p| p.bind(&|p| p.lam_star(char_rule), "cs")),
            quote,
            &|p| {
                p.lam(|p| {
                    let cs = p.get("cs")?;
                    let joined = p.join(&cs)?;
                    p.succeed(joined, None)
                })
            },
        ])
    }

    fn sqchar(&mut self) -> R {
        self.qchar(&|p| p.squote())
    }

    fn dqchar(&mut self) -> R {
        self.qchar(&|p| p.dquote())
    }

    /// `_sqchar_` and `_dqchar_`.
    fn qchar(&mut self, quote: Rule) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.bslash(),
                        &|p| p.lam_bind(&|p| p.esc_char(), "c"),
                        &|p| p.lam_succeed_get("c"),
                    ])
                },
                &|p| {
                    p.frame(|p| {
                        p.seq(&[&|p| p.bslash(), &|p| p.eol(), &|p| {
                            p.lam_succeed(V::text(""))
                        }])
                    })
                },
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.lam_not(&|p| p.bslash()),
                        &|p| p.lam_not(quote),
                        &|p| p.lam_not(&|p| p.eol()),
                        &|p| p.lam_bind(&|p| p.anything(), "c"),
                        &|p| p.lam_succeed_get("c"),
                    ])
                },
                &|p| {
                    p.frame(|p| {
                        p.seq(
                            &[&|p| p.lam_not(&|p| p.frame(|p| p.flag("_strict"))), &|p| {
                                p.lam(|p| p.range('\u{0}', '\u{1f}'))
                            }],
                        )
                    })
                },
            ])
        })
    }

    fn bslash(&mut self) -> R {
        self.frame(|p| p.ch('\\'))
    }

    fn squote(&mut self) -> R {
        self.frame(|p| p.ch('\''))
    }

    fn dquote(&mut self) -> R {
        self.frame(|p| p.ch('"'))
    }

    fn esc_char(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.esc_simple('b', '\u{8}'),
                &|p| p.esc_simple('f', '\u{c}'),
                &|p| p.esc_simple('n', '\n'),
                &|p| p.esc_simple('r', '\r'),
                &|p| p.esc_simple('t', '\t'),
                &|p| p.esc_simple('v', '\u{b}'),
                &|p| p.esc_quoted(&|p| p.squote(), "'"),
                &|p| p.esc_quoted(&|p| p.dquote(), "\""),
                &|p| p.esc_quoted(&|p| p.bslash(), "\\"),
                &|p| p.esc_char_c9(),
                &|p| {
                    p.frame(|p| {
                        p.seq(&[&|p| p.lam_ch('0'), &|p| p.lam_not(&|p| p.digit()), &|p| {
                            p.lam_succeed(V::ch(0))
                        }])
                    })
                },
                &|p| {
                    p.scoped_seq(&[&|p| p.lam_bind(&|p| p.hex_esc(), "c"), &|p| {
                        p.lam_succeed_get("c")
                    }])
                },
                &|p| {
                    p.scoped_seq(&[&|p| p.lam_bind(&|p| p.unicode_esc(), "c"), &|p| {
                        p.lam_succeed_get("c")
                    }])
                },
            ])
        })
    }

    /// `_esc_char__c0_` to `_esc_char__c5_`.
    fn esc_simple(&mut self, letter: char, value: char) -> R {
        self.frame(|p| {
            p.seq(&[&|p| p.lam_ch(letter), &|p| {
                p.lam_succeed(V::ch(u32::from(value)))
            }])
        })
    }

    /// `_esc_char__c6_` to `_esc_char__c8_`.
    fn esc_quoted(&mut self, rule: Rule, value: &'static str) -> R {
        self.frame(|p| p.seq(&[rule, &|p| p.lam_succeed(V::text(value))]))
    }

    fn esc_char_c9(&mut self) -> R {
        self.scoped_seq(&[
            &|p| {
                p.frame(|p| {
                    p.not(&|p| {
                        p.lam(|p| {
                            p.frame(|p| {
                                p.choose(&[
                                    &|p| p.frame(|p| p.seq(&[&|p| p.lam_ch('x')])),
                                    &|p| p.frame(|p| p.seq(&[&|p| p.lam_ch('u')])),
                                    &|p| p.lam(|p| p.seq(&[&|p| p.digit()])),
                                    &|p| p.lam(|p| p.seq(&[&|p| p.eol()])),
                                ])
                            })
                        })
                    })
                })
            },
            &|p| p.lam_bind(&|p| p.anything(), "c"),
            &|p| p.lam_succeed_get("c"),
        ])
    }

    fn hex_esc(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.lam_ch('x'),
            &|p| p.lam_bind(&|p| p.hex(), "h1"),
            &|p| p.lam_bind(&|p| p.hex(), "h2"),
            &|p| p.lam_succeed_xtou(&["h1", "h2"]),
        ])
    }

    fn unicode_esc(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.lam_ch('u'),
            &|p| p.lam_bind(&|p| p.hex(), "a"),
            &|p| p.lam_bind(&|p| p.hex(), "b"),
            &|p| p.lam_bind(&|p| p.hex(), "c"),
            &|p| p.lam_bind(&|p| p.hex(), "d"),
            &|p| p.lam_succeed_xtou(&["a", "b", "c", "d"]),
        ])
    }

    /// `lambda: self._succeed(self._xtou(self._get(..) + ...))`.
    fn lam_succeed_xtou(&mut self, vars: &[&'static str]) -> R {
        self.lam(|p| {
            let mut digits = p.get(vars[0])?;
            for var in &vars[1..] {
                digits = digits.add(&p.get(var)?);
            }
            let c = p.xtou(&digits)?;
            p.succeed(c, None)
        })
    }

    fn element_list(&mut self) -> R {
        self.item_list(&|p| p.value(), "v", "vs")
    }

    fn member_list(&mut self) -> R {
        self.item_list(&|p| p.member(), "m", "ms")
    }

    /// `_element_list_` and `_member_list_`.
    fn item_list(&mut self, item: Rule, one: &'static str, rest: &'static str) -> R {
        self.scoped_seq(&[
            &|p| p.lam_bind(item, one),
            &|p| {
                p.frame(|p| {
                    p.bind(
                        &|p| {
                            p.lam_star(&|p| {
                                p.frame(|p| {
                                    p.seq(&[&|p| p.sp(), &|p| p.lam_ch(','), &|p| p.sp(), item])
                                })
                            })
                        },
                        rest,
                    )
                })
            },
            &|p| p.sp(),
            &|p| p.frame(|p| p.opt(&|p| p.lam_ch(','))),
            &|p| {
                p.lam(|p| {
                    let first = V::new_list(vec![p.get(one)?]);
                    let others = p.get(rest)?;
                    p.succeed(first.add(&others), None)
                })
            },
        ])
    }

    fn member(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[&|p| p.member_c(&|p| p.string()), &|p| {
                p.member_c(&|p| p.ident())
            }])
        })
    }

    /// `_member__c0_` and `_member__c1_`.
    fn member_c(&mut self, key: Rule) -> R {
        self.scoped_seq(&[
            &|p| p.lam_bind(key, "k"),
            &|p| p.sp(),
            &|p| p.lam_ch(':'),
            &|p| p.sp(),
            &|p| p.lam_bind(&|p| p.value(), "v"),
            &|p| {
                p.lam(|p| {
                    let k = p.get("k")?;
                    let v = p.get("v")?;
                    p.succeed(V::new_list(vec![k, v]), None)
                })
            },
        ])
    }

    fn ident(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.lam_bind(&|p| p.id_start(), "hd"),
            &|p| p.frame(|p| p.bind(&|p| p.lam_star(&|p| p.id_continue()), "tl")),
            &|p| {
                p.lam(|p| {
                    let hd = V::new_list(vec![p.get("hd")?]);
                    let tl = p.get("tl")?;
                    let joined = p.join(&hd.add(&tl))?;
                    p.succeed(joined, None)
                })
            },
        ])
    }

    fn id_start(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[&|p| p.ascii_id_start(), &|p| p.other_id_start(), &|p| {
                p.frame(|p| p.seq(&[&|p| p.bslash(), &|p| p.unicode_esc()]))
            }])
        })
    }

    fn ascii_id_start(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.frame(|p| p.range('a', 'z')),
                &|p| p.frame(|p| p.range('A', 'Z')),
                &|p| p.frame(|p| p.ch('$')),
                &|p| p.frame(|p| p.ch('_')),
            ])
        })
    }

    fn other_id_start(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.unicat_char(LL),
                &|p| p.unicat_char(LM),
                &|p| p.unicat_char(LO),
                &|p| p.unicat_char(LT),
                &|p| p.unicat_char(LU),
                &|p| p.unicat_char(NL),
            ])
        })
    }

    /// `_other_id_start__cN_` and `_id_continue__c3_` to `_id_continue__c6_`.
    fn unicat_char(&mut self, category: &'static [(u32, u32)]) -> R {
        self.scoped_seq(&[
            &|p| p.lam_bind(&|p| p.anything(), "x"),
            &|p| p.frame(|p| p.unicat_check(category)),
            &|p| p.lam_succeed_get("x"),
        ])
    }

    fn id_continue(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.ascii_id_start(),
                &|p| p.digit(),
                &|p| p.other_id_start(),
                &|p| p.unicat_char(MN),
                &|p| p.unicat_char(MC),
                &|p| p.unicat_char(ND),
                &|p| p.unicat_char(PC),
                &|p| p.frame(|p| p.seq(&[&|p| p.bslash(), &|p| p.unicode_esc()])),
                &|p| p.frame(|p| p.ch('\u{200c}')),
                &|p| p.frame(|p| p.ch('\u{200d}')),
            ])
        })
    }

    fn num_literal(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.lam_ch('-'),
                        &|p| p.lam_bind(&|p| p.unsigned_lit(), "n"),
                        &|p| {
                            p.lam(|p| {
                                let n = p.get("n")?;
                                p.succeed(V::text("-").add(&n), None)
                            })
                        },
                    ])
                },
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.lam_ch('+'),
                        &|p| p.lam_bind(&|p| p.unsigned_lit(), "n"),
                        &|p| p.lam_succeed_get("n"),
                    ])
                },
                &|p| {
                    p.scoped_seq(&[&|p| p.lam_bind(&|p| p.unsigned_lit(), "n"), &|p| {
                        p.lam_succeed_get("n")
                    }])
                },
            ])
        })
    }

    fn unsigned_lit(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.lam_bind(&|p| p.dec_literal(), "d"),
                        &|p| p.lam_not(&|p| p.id_start()),
                        &|p| p.lam_succeed_get("d"),
                    ])
                },
                &|p| p.hex_literal(),
                &|p| p.frame(|p| p.str_("Infinity")),
                &|p| p.frame(|p| p.str_("NaN")),
            ])
        })
    }

    fn dec_literal(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.dec_parts(&["d", "f", "e"]),
                &|p| p.dec_parts(&["d", "f"]),
                &|p| p.dec_parts(&["d", "e"]),
                &|p| p.dec_parts(&["d"]),
                &|p| p.dec_parts(&["f", "e"]),
                &|p| p.dec_parts(&["f"]),
            ])
        })
    }

    /// `_dec_literal__c0_` to `_dec_literal__c5_`: binds each part in turn,
    /// then succeeds with their concatenation.
    fn dec_parts(&mut self, parts: &'static [&'static str]) -> R {
        let binds: Vec<_> = parts
            .iter()
            .map(|&part| {
                move |p: &mut P| -> R {
                    let rule: Rule = match part {
                        "d" => &|p| p.dec_int_lit(),
                        "f" => &|p| p.frac(),
                        _ => &|p| p.exp(),
                    };
                    p.lam_bind(rule, part)
                }
            })
            .collect();
        let finish = |p: &mut P| -> R {
            p.lam(|p| {
                let mut v = p.get(parts[0])?;
                for part in &parts[1..] {
                    v = v.add(&p.get(part)?);
                }
                p.succeed(v, None)
            })
        };
        let rules: Vec<Rule> = binds
            .iter()
            .map(|bind| bind as Rule)
            .chain(std::iter::once(&finish as Rule))
            .collect();
        self.scoped_seq(&rules)
    }

    fn dec_int_lit(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| {
                    p.frame(|p| {
                        p.seq(&[&|p| p.lam_ch('0'), &|p| p.lam_not(&|p| p.digit()), &|p| {
                            p.lam_succeed(V::text("0"))
                        }])
                    })
                },
                &|p| {
                    p.scoped_seq(&[
                        &|p| p.lam_bind(&|p| p.nonzerodigit(), "d"),
                        &|p| p.frame(|p| p.bind(&|p| p.lam_star(&|p| p.digit()), "ds")),
                        &|p| {
                            p.lam(|p| {
                                let d = p.get("d")?;
                                let ds = p.get("ds")?;
                                let joined = p.join(&ds)?;
                                p.succeed(d.add(&joined), None)
                            })
                        },
                    ])
                },
            ])
        })
    }

    fn digit(&mut self) -> R {
        self.frame(|p| p.range('0', '9'))
    }

    fn nonzerodigit(&mut self) -> R {
        self.frame(|p| p.range('1', '9'))
    }

    fn hex_literal(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.frame(|p| p.choose(&[&|p| p.lam_str("0x"), &|p| p.lam_str("0X")])),
            &|p| p.frame(|p| p.bind(&|p| p.lam(|p| p.plus(&|p| p.hex())), "hs")),
            &|p| p.lam_succeed_prefixed("0x", "hs"),
        ])
    }

    fn hex(&mut self) -> R {
        self.frame(|p| {
            p.choose(&[
                &|p| p.frame(|p| p.range('a', 'f')),
                &|p| p.frame(|p| p.range('A', 'F')),
                &|p| p.digit(),
            ])
        })
    }

    fn frac(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.lam_ch('.'),
            &|p| p.frame(|p| p.bind(&|p| p.lam_star(&|p| p.digit()), "ds")),
            &|p| p.lam_succeed_prefixed(".", "ds"),
        ])
    }

    /// `lambda: self._succeed(prefix + self._join('', self._get(var)))`.
    fn lam_succeed_prefixed(&mut self, prefix: &'static str, var: &'static str) -> R {
        self.lam(|p| {
            let vs = p.get(var)?;
            let joined = p.join(&vs)?;
            p.succeed(V::text(prefix).add(&joined), None)
        })
    }

    fn exp(&mut self) -> R {
        self.frame(|p| p.choose(&[&|p| p.exp_c0(), &|p| p.exp_c1()]))
    }

    fn exp_marker(&mut self) -> R {
        self.frame(|p| p.choose(&[&|p| p.lam_ch('e'), &|p| p.lam_ch('E')]))
    }

    fn exp_c0(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.exp_marker(),
            &|p| {
                p.lam_bind(
                    &|p| p.frame(|p| p.choose(&[&|p| p.lam_ch('+'), &|p| p.lam_ch('-')])),
                    "s",
                )
            },
            &|p| p.frame(|p| p.bind(&|p| p.lam_star(&|p| p.digit()), "ds")),
            &|p| {
                p.lam(|p| {
                    let s = p.get("s")?;
                    let ds = p.get("ds")?;
                    let joined = p.join(&ds)?;
                    p.succeed(V::text("e").add(&s).add(&joined), None)
                })
            },
        ])
    }

    fn exp_c1(&mut self) -> R {
        self.scoped_seq(&[
            &|p| p.exp_marker(),
            &|p| p.frame(|p| p.bind(&|p| p.lam_star(&|p| p.digit()), "ds")),
            &|p| p.lam_succeed_prefixed("e", "ds"),
        ])
    }
}
